# =============================================================================# SETUP POWER PLAN - Cegah PC Sleep/Hibernate# Jalankan SEKALI sebagai Administrator# =============================================================================Write-Host "================================================" -ForegroundColor CyanWrite-Host "   SETUP POWER PLAN - CEGAH PC SLEEP/HIBERNATE" -ForegroundColor CyanWrite-Host "================================================" -ForegroundColor CyanWrite-Host ""# Aktifkan skema High Performancepowercfg /setactive 8c5e7fda-e8bf-4a96-9a85-a6e23a8c635cWrite-Host "[OK] Power plan: High Performance diaktifkan" -ForegroundColor Green# Monitor boleh mati, tapi sistem tidak boleh sleep# Sleep setelah 0 menit = tidak pernah sleep (AC power)powercfg /change standby-timeout-ac 0powercfg /change hibernate-timeout-ac 0powercfg /change monitor-timeout-ac 30Write-Host "[OK] Standby/Hibernate (AC): DINONAKTIFKAN" -ForegroundColor GreenWrite-Host "[OK] Monitor timeout: 30 menit (hemat listrik)" -ForegroundColor Green# Nonaktifkan Fast Startup (kadang bermasalah dengan Docker)$regPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power"Set-ItemProperty -Path $regPath -Name "HiberbootEnabled" -Value 0 -Type DWord -ErrorAction SilentlyContinueWrite-Host "[OK] Fast Startup: DINONAKTIFKAN (agar Docker berjalan stabil)" -ForegroundColor GreenWrite-Host ""Write-Host "================================================" -ForegroundColor CyanWrite-Host " SELESAI! PC tidak akan sleep selama terhubung AC" -ForegroundColor GreenWrite-Host "================================================" -ForegroundColor Cyan